1	package vae
2	
3	import (
4		"context"
5		"fmt"
6		"math"
7		"time"
8		"unsafe"
9	
10		"strix-halo-vulkan/shaders"
11		"strix-halo-vulkan/vk"
12		zvae "strix-halo-vulkan/zimage/vae"
13	)
14	
15	// The decoder on the device — IMAGE.md Q5g, the stage that stood between
16	// Q4's 2.27 s DiT step and a served image.
17	//
18	// The CPU decoder in vae.go is the oracle and is also the reason this file
19	// exists: it decodes 256x256 in ~20 s, and the graph is 16x larger at
20	// 1024x1024, so a served generation would have spent minutes downstream of
21	// a 91 s transformer.
22	//
23	// Almost none of it is new. z-image's decoder graph (zimage/vae/gpu.go)
24	// established the shape — one weight arena written once, one activation
25	// arena a bump allocator ping-pongs inside, "which tensor" as an offset
26	// rather than a descriptor rebind, and the whole decode recorded as a
27	// dispatch list — and its kernels do the work here unchanged: the
28	// register-blocked fp32 convolution, the 2x nearest upsample, the add, and
29	// the mid block's row-major attention with its transposed K. Three things
30	// in this VAE are genuinely not in that one, and each is one shader:
31	//
32	//   - the norm. RMS_norm here is a per-pixel L2 normalize across channels,
33	//     not a group norm, and it is always followed by a SiLU — qvae_chnorm
34	//     does both in one pass;
35	//   - the up blocks' parameter-free channel-to-space shortcut, whose
36	//     channel mapping depends on a video model's temporal factor even
37	//     though no temporal axis survives at T = 1 — qvae_dupup;
38	//   - the mid block is 1152 channels wide where z-image's is 512, which the
39	//     scalar attention kernel needs as a compile-time bound.
40	//
41	// The mid block's four projections are 1x1 convolutions, which is to say
42	// linears over the pixel rows, and to_qkv's [3C, C] weight is three of them
43	// stacked — so the graph reads it at three offsets rather than splitting the
44	// tensor. That is why there is no qkv convolution in the dispatch list.
45	//
46	// Everything here is fp32. Q0 measured this decoder's intermediates at
47	// absmax ~1e5–3e5 against fp16's 65504, so the matrix-core convolution that
48	// took z-image's decode from 3.18 s to 258 ms cannot simply be pointed at
49	// this graph; what it would take is priced in gpu_test.go's range
50	// measurement, and it is Q9's, not Q5g's.
51	
52	// pushConstants mirrors the PC block in shaders/vae_common.glsl. Every
53	// pipeline in the graph declares the same block, because vk.DispatchMultiTimed
54	// records the whole thing into one command buffer and requires one
55	// push-constant size across it.
56	type pushConstants struct {
57		InOff, OutOff    uint32
58		C, H, W          uint32
59		OC, KH, KW, Pad  uint32
60		WOff, BOff       uint32
61		Groups           uint32
62		ResOff           uint32
63		Aux0, Aux1, Aux2 uint32
64		// The GEMM block, unused on this path but part of the layout: the block's
65		// size is fixed by the shaders the graph borrows.
66		GemmB, GemmM, GemmN, GemmK uint32
67		LDA, LDB                   uint32
68	}
69	
70	const noBias = 0xffffffff
71	
72	// dispatchesPerSubmit caps how much work goes into one command buffer. The
73	// whole graph in a single submit trips the driver's reset watchdog and comes
74	// back as VK_ERROR_DEVICE_LOST; the same dispatches submitted in batches all
75	// complete. 4 is z-image's measured-free value and this graph's dispatches
76	// are no larger than that one's.
77	const dispatchesPerSubmit = 4
78	
79	func (p pushConstants) bytes() []byte {
80		out := make([]byte, unsafe.Sizeof(p))
81		*(*pushConstants)(unsafe.Pointer(&out[0])) = p
82		return out
83	}
84	
85	// arena hands out element offsets inside one activation buffer, with a
86	// best-fit free list. It is zimage/vae's, for the reason that file gives:
87	// an up block's input is twice the channel count of what its resnets
88	// produce, so exact-size bucketing fills the arena with large blocks that
89	// can never serve the smaller requests that follow.
90	type arena struct {
91		next uint32
92		high uint32
93		free []freeBlock
94	}
95	
96	type freeBlock struct {
97		off  uint32
98		size uint32
99	}
100	
101	func roundUp(elems int) uint32 { return uint32((elems + 63) &^ 63) }
102	
103	func (a *arena) alloc(elems int) uint32 {
104		n := roundUp(elems)
105		best := -1
106		for i, b := range a.free {
107			if b.size >= n && (best < 0 || b.size < a.free[best].size) {
108				best = i
109			}
110		}
111		if best >= 0 {
112			blk := a.free[best]
113			a.free = append(a.free[:best], a.free[best+1:]...)
114			if rem := blk.size - n; rem >= 64 {
115				a.free = append(a.free, freeBlock{off: blk.off + n, size: rem})
116			}
117			return blk.off
118		}
119		off := a.next
120		a.next += n
121		if a.next > a.high {
122			a.high = a.next
123		}
124		return off
125	}
126	
127	// release returns a block, coalescing with neighbours and giving back to the
128	// bump pointer anything that now ends at it.
129	func (a *arena) release(off uint32, elems int) {
130		blk := freeBlock{off: off, size: roundUp(elems)}
131		for merged := true; merged; {
132			merged = false
133			for i, b := range a.free {
134				if b.off+b.size == blk.off {
135					blk.off, blk.size = b.off, b.size+blk.size
136				} else if blk.off+blk.size == b.off {
137					blk.size += b.size
138				} else {
139					continue
140				}
141				a.free = append(a.free[:i], a.free[i+1:]...)
142				merged = true
143				break
144			}
145		}
146		a.free = append(a.free, blk)
147		for {
148			i := -1
149			for j, b := range a.free {
150				if b.off+b.size == a.next {
151					i = j
152					break
153				}
154			}
155			if i < 0 {
156				return
157			}
158			a.next = a.free[i].off
159			a.free = append(a.free[:i], a.free[i+1:]...)
160		}
161	}
162	
163	func (a *arena) reset() {
164		a.next = 0
165		a.free = nil
166	}
167	
168	// gpuWeights is the flat fp32 weight arena plus every tensor's offset in it.
169	type gpuWeights struct {
170		data []float32
171		off  map[string]uint32
172	}
173	
174	func (g *gpuWeights) put(name string, v []float32) {
175		g.off[name] = uint32(len(g.data))
176		g.data = append(g.data, v...)
177	}
178	
179	// midDim is the channel width the attention kernel was built for. The build
180	// is shaders.VAEAttentionDim1152 and the bound is a shared-array extent, so
181	// a checkpoint with a different mid width would silently write past it — it
182	// is refused at load instead.
183	const midDim = 1152
184	
185	// engine is the Vulkan half of a graph on this device: the two buffers, the
186	// pipelines, the flattened weights and the activation arena. The decoder and
187	// the encoder are two graphs over one set of kernels, so this is what they
188	// share — the same split zimage/vae made between its own two directions.
189	type engine struct {
190		dev *vk.Device
191	
192		wbuf *vk.Buffer
193		abuf *vk.Buffer
194	
195		pipes   map[string]*vk.ComputePipeline
196		mods    []*vk.ShaderModule
197		weights *gpuWeights
198	
199		arena arena
200	}
201	
202	// stage uploads the weights, sizes the arena and builds every pipeline.
203	func (e *engine) stage(dev *vk.Device, set map[string][]byte, arenaElems uint32) error {
204		e.dev = dev
205		var err error
206		wbytes := len(e.weights.data) * 4
207		if e.wbuf, err = dev.NewBuffer(wbytes); err != nil {
208			return fmt.Errorf("qvae: weight buffer (%d MB): %w", wbytes>>20, err)
209		}
210		e.wbuf.WriteFloat32(e.weights.data)
211		if e.abuf, err = dev.NewBuffer(int(arenaElems) * 4); err != nil {
212			return fmt.Errorf("qvae: activation buffer (%d MB): %w", (int(arenaElems)*4)>>20, err)
213		}
214		bufs := []*vk.Buffer{e.wbuf, e.abuf}
215		pcSize := uint32(unsafe.Sizeof(pushConstants{}))
216		for name, spirv := range set {
217			mod, err := dev.NewShaderModule(spirv)
218			if err != nil {
219				return fmt.Errorf("qvae: shader %s: %w", name, err)
220			}
221			e.mods = append(e.mods, mod)
222			pipe, err := dev.NewPipeline(mod, vk.PipelineSpec{Buffers: bufs, PushConstantSize: pcSize})
223			if err != nil {
224				return fmt.Errorf("qvae: pipeline %s: %w", name, err)
225			}
226			e.pipes[name] = pipe
227		}
228		return nil
229	}
230	
231	func (e *engine) destroy() {
232		for _, p := range e.pipes {
233			p.Destroy()
234		}
235		for _, m := range e.mods {
236			m.Destroy()
237		}
238		for _, b := range []*vk.Buffer{e.abuf, e.wbuf} {
239			if b != nil {
240				b.Destroy()
241			}
242		}
243		e.pipes, e.mods = map[string]*vk.ComputePipeline{}, nil
244		e.abuf, e.wbuf = nil, nil
245	}
246	
247	// run submits a prefix of a recorded graph, to completion.
248	func (e *engine) run(ds []vk.MultiDispatch) error {
249		return e.runContext(context.Background(), ds)
250	}
251	
252	// runContext is run with a cancellation point, and the batching this graph
253	// already does for the driver's sake is what provides one.
254	//
255	// A submitted command buffer has no cancellation point inside it — the fence
256	// is waited on or the device is left mid-graph — so the finest granularity
257	// available is *between* submits. That is already every four dispatches
258	// (dispatchesPerSubmit, a watchdog constraint rather than a choice), which
259	// puts a 1024² decode's 117 dispatches at 30 batches of ~250 ms. So a client
260	// that hangs up during a decode stops paying for it within a quarter of a
261	// second instead of 7.5 s, and the device lock is released that much sooner
262	// for whoever is queued behind them.
263	//
264	// The error wraps ctx.Err(), so `errors.Is(err, context.Canceled)` holds all
265	// the way up to the handler, which is where it becomes "no answer" rather
266	// than a 500.
267	func (e *engine) runContext(ctx context.Context, ds []vk.MultiDispatch) error {
268		for i := 0; i < len(ds); i += dispatchesPerSubmit {
269			if err := ctx.Err(); err != nil {
270				return fmt.Errorf("qvae: cancelled after %d of %d dispatches: %w", i, len(ds), err)
271			}
272			j := min(i+dispatchesPerSubmit, len(ds))
273			if _, err := vk.DispatchMultiTimed(ds[i:j], 1, 1, true); err != nil {
274				return fmt.Errorf("qvae: dispatch %d-%d: %w", i, j-1, err)
275			}
276		}
277		return nil
278	}
279	
280	// read copies one arena tensor back.
281	func (e *engine) read(t tensor) *zvae.Tensor {
282		out := zvae.NewTensor(1, t.C, t.H, t.W)
283		copy(out.Data, e.abuf.ReadFloat32At(int(t.off), t.elems()))
284		return out
285	}
286	
287	// ActivationBytes and WeightBytes are what the graph costs in device memory.
288	func (e *engine) ActivationBytes() int { return e.abuf.Size() }
289	func (e *engine) WeightBytes() int     { return e.wbuf.Size() }
290	
291	// newEngine is an engine with its maps made but nothing staged, which is also
292	// what the sizing passes record against.
293	func newEngine() engine {
294		return engine{
295			pipes:   make(map[string]*vk.ComputePipeline),
296			weights: &gpuWeights{off: make(map[string]uint32)},
297		}
298	}
299	
300	// GPUDecoder runs the decode graph on a Vulkan device.
301	type GPUDecoder struct {
302		engine
303		cpu *Decoder
304	}
305	
306	// shaderSet is every pipeline the graph uses. Six of the eight are z-image's
307	// unchanged.
308	var shaderSet = map[string][]byte{
309		"conv2d":     shaders.VAEConv2D,
310		"add":        shaders.VAEAdd,
311		"upsample2x": shaders.VAEUpsample2x,
312		"to_rows":    shaders.VAENCHWToRows,
313		"to_nchw":    shaders.VAERowsToNCHWAdd,
314		"linear":     shaders.VAELinear,
315		"transpose":  shaders.VAETranspose,
316		"attention":  shaders.VAEAttentionDim1152,
317		"chnorm":     shaders.QVAEChannelNorm,
318		"dupup":      shaders.QVAEDupUp,
319	}
320	
321	// NewGPUDecoder uploads a loaded decoder's weights, builds its pipelines and
322	// sizes the activation arena for a latentH x latentW latent — which is the
323	// largest the returned decoder will accept, since the arena is allocated
324	// once.
325	func NewGPUDecoder(dev *vk.Device, cpu *Decoder, latentH, latentW int) (*GPUDecoder, error) {
326		if got := cpu.Mid.Attn.QKV.InC; got != midDim {
327			return nil, fmt.Errorf("qvae: mid block is %d channels, the attention kernel is built for %d", got, midDim)
328		}
329		g := &GPUDecoder{engine: newEngine(), cpu: cpu}
330		g.flattenWeights()
331	
332		need, err := g.planSize(latentH, latentW)
333		if err != nil {
334			g.Destroy()
335			return nil, err
336		}
337		if err := g.stage(dev, shaderSet, need); err != nil {
338			g.Destroy()
339			return nil, err
340		}
341		return g, nil
342	}
343	
344	// Destroy releases every Vulkan object.
345	func (g *GPUDecoder) Destroy() { g.destroy() }
346	
347	// flattenWeights copies every weight the graph reads into one arena, in the
348	// order the graph reads them. to_qkv stays one [3C, C] tensor: the three
349	// projections are its three row blocks, and the graph addresses them by
350	// offset.
351	func (g *GPUDecoder) flattenWeights() {
352		w := g.weights
353		conv := func(name string, c *zvae.Conv2D) {
354			w.put(name+".weight", c.Weight)
355			if c.Bias != nil {
356				w.put(name+".bias", c.Bias)
357			}
358		}
359		norm := func(name string, n *ChannelNorm) { w.put(name+".gamma", n.Gamma) }
360		res := func(name string, r *ResBlock) {
361			norm(name+".norm1", &r.Norm1)
362			conv(name+".conv1", &r.Conv1)
363			norm(name+".norm2", &r.Norm2)
364			conv(name+".conv2", &r.Conv2)
365			if r.Shortcut != nil {
366				conv(name+".shortcut", r.Shortcut)
367			}
368		}
369	
370		d := g.cpu
371		conv("post_quant", &d.PostQuant)
372		conv("conv_in", &d.ConvIn)
373		res("mid.r1", &d.Mid.Res1)
374		norm("mid.attn.norm", &d.Mid.Attn.Norm)
375		conv("mid.attn.qkv", &d.Mid.Attn.QKV)
376		conv("mid.attn.proj", &d.Mid.Attn.Proj)
377		res("mid.r2", &d.Mid.Res2)
378		for i := range d.Ups {
379			up := &d.Ups[i]
380			for j := range up.Resnets {
381				res(fmt.Sprintf("up.%d.r%d", i, j), &up.Resnets[j])
382			}
383			if up.Up != nil {
384				conv(fmt.Sprintf("up.%d.upconv", i), &up.Up.Conv)
385			}
386		}
387		norm("norm_out", &d.NormOut)
388		conv("conv_out", &d.ConvOut)
389	}
390	
391	// tensor is a shape plus its offset in the activation arena.
392	type tensor struct {
393		off     uint32
394		C, H, W int
395	}
396	
397	func (t tensor) elems() int { return t.C * t.H * t.W }
398	
399	// builder records a graph into a dispatch list. It is shared by both
400	// directions: the decoder and the encoder differ in what they record, not in
401	// how it is recorded.
402	type builder struct {
403		e     *engine
404		ar    *arena
405		out   []vk.MultiDispatch
406		kinds []string
407		flops []float64
408	
409		pendingKind  string
410		pendingFlops float64
411		pendingIn    tensor
412	
413		// ins is each dispatch's input tensor where one convolution reads one
414		// tensor, and the zero value otherwise. ConvInputRanges is its only
415		// reader: what a matrix-core convolution would need to know about this
416		// graph is whether the operand it narrows fits in fp16, and that is a
417		// property of these tensors.
418		ins []tensor
419	
420		// marks names the tensor each named stage leaves behind and the dispatch
421		// that finishes it. A bump-allocated graph overwrites every intermediate
422		// long before it ends, so the only way to look at one is to re-run the
423		// prefix and stop — which is what RunTo does and what the stagewise gate
424		// in gpu_test.go needs.
425		marks map[string]tensor
426		order []string
427		stops []int
428	
429		err error
430	}
431	
432	func (b *builder) mark(name string, t tensor) tensor {
433		if b.marks != nil {
434			b.marks[name] = t
435			b.order = append(b.order, name)
436			b.stops = append(b.stops, len(b.out))
437		}
438		return t
439	}
440	
441	func (b *builder) label(kind string, flops float64) {
442		b.pendingKind, b.pendingFlops = kind, flops
443	}
444	
445	func groups(n, local int) uint32 { return uint32((n + local - 1) / local) }
446	
447	func (b *builder) add(pipe string, gx uint32, pc pushConstants) {
448		b.addXY(pipe, gx, 1, pc)
449	}
450	
451	func (b *builder) addXY(pipe string, gx, gy uint32, pc pushConstants) {
452		if b.err != nil {
453			return
454		}
455		// planSize records the same graph with no pipelines built, purely to size
456		// the arena, so a missing pipeline is an error only once there are any.
457		p := b.e.pipes[pipe]
458		if p == nil && len(b.e.pipes) > 0 {
459			b.err = fmt.Errorf("qvae: no pipeline %q", pipe)
460			return
461		}
462		b.out = append(b.out, vk.MultiDispatch{Pipeline: p, GroupsX: gx, GroupsY: gy, PushConstants: pc.bytes()})
463		kind := b.pendingKind
464		if kind == "" {
465			kind = pipe
466		}
467		b.kinds = append(b.kinds, kind)
468		b.flops = append(b.flops, b.pendingFlops)
469		b.ins = append(b.ins, b.pendingIn)
470		b.pendingKind, b.pendingFlops, b.pendingIn = "", 0, tensor{}
471	}
472	
473	func (b *builder) release(ts ...tensor) {
474		for _, t := range ts {
475			b.ar.release(t.off, t.elems())
476		}
477	}
478	
479	// wOff resolves a weight. A missing one is an error only once there are
480	// pipelines to dispatch — the same condition as addXY, and for the same
481	// reason: the sizing pass records the graph against neither.
482	func (b *builder) wOff(name string) uint32 {
483		off, ok := b.e.weights.off[name]
484		if !ok && b.err == nil && len(b.e.pipes) > 0 {
485			b.err = fmt.Errorf("qvae: no weight %q", name)
486		}
487		return off
488	}
489	
490	func (b *builder) bOff(name string) uint32 {
491		if off, ok := b.e.weights.off[name]; ok {
492			return off
493		}
494		return noBias
495	}
496	
497	// conv appends a convolution producing a fresh tensor. Both shapes the
498	// decoder uses — 3x3 pad 1 and the 1x1 pad 0 shortcuts and projections —
499	// preserve H and W.
500	func (b *builder) conv(name string, c *zvae.Conv2D, x tensor) tensor {
501		out := tensor{off: b.ar.alloc(c.OutC * x.H * x.W), C: c.OutC, H: x.H, W: x.W}
502		b.label(fmt.Sprintf("conv%dx%d %d->%d @%dx%d", c.KH, c.KW, x.C, c.OutC, x.H, x.W),
503			2*float64(c.OutC)*float64(x.H)*float64(x.W)*float64(x.C)*float64(c.KH)*float64(c.KW))
504		b.pendingIn = x
505		// The grid's y axis is output-channel blocks: the shader holds OC_BLOCK
506		// accumulators per thread, which is where its arithmetic intensity is.
507		const convOCBlock = 8
508		b.addXY("conv2d", groups(out.H*out.W, 256), groups(c.OutC, convOCBlock), pushConstants{
509			InOff: x.off, OutOff: out.off,
510			C: uint32(x.C), H: uint32(x.H), W: uint32(x.W),
511			OC: uint32(c.OutC), KH: uint32(c.KH), KW: uint32(c.KW), Pad: uint32(c.Pad),
512			WOff: b.wOff(name + ".weight"), BOff: b.bOff(name + ".bias"),
513		})
514		return out
515	}
516	
517	// chnorm appends the channel norm, optionally with its SiLU fused. dst may
518	// be src: one thread owns one pixel's whole channel column, so writing it
519	// back over the read is safe and saves a tensor.
520	func (b *builder) chnorm(name string, silu bool, src, dst tensor) tensor {
521		aux := uint32(0)
522		if silu {
523			aux = 1
524		}
525		b.label(fmt.Sprintf("chnorm %d @%dx%d", src.C, src.H, src.W), 0)
526		b.add("chnorm", groups(src.H*src.W, 256), pushConstants{
527			InOff: src.off, OutOff: dst.off,
528			C: uint32(src.C), H: uint32(src.H), W: uint32(src.W),
529			WOff: b.wOff(name + ".gamma"),
530			Aux0: aux,
531		})
532		return dst
533	}
534	
535	// addInto appends a += res.
536	func (b *builder) addInto(a, res tensor) tensor {
537		b.add("add", groups(a.elems(), 256), pushConstants{
538			InOff: a.off, OutOff: a.off, ResOff: res.off, Aux0: uint32(a.elems()),
539		})
540		return a
541	}
542	
543	// resblock records one residual block. keepIn leaves the input allocated,
544	// which the up blocks need: their parameter-free shortcut reads the block's
545	// input after all three resnets have run.
546	//
547	// Every release happens after the dispatch that consumes the tensor is
548	// recorded and after the next tensor is allocated; releasing earlier would
549	// let the allocator hand the same block to a tensor still being read.
550	func (b *builder) resblock(name string, r *ResBlock, x tensor, keepIn bool) tensor {
551		// norm1 writes into a fresh tensor rather than over x: x is the residual
552		// and is read again at the end of the block.
553		h := tensor{off: b.ar.alloc(x.elems()), C: x.C, H: x.H, W: x.W}
554		b.chnorm(name+".norm1", true, x, h)
555	
556		h1 := b.conv(name+".conv1", &r.Conv1, h)
557		b.release(h)
558		b.chnorm(name+".norm2", true, h1, h1)
559	
560		h2 := b.conv(name+".conv2", &r.Conv2, h1)
561		b.release(h1)
562	
563		skip := x
564		if r.Shortcut != nil {
565			skip = b.conv(name+".shortcut", r.Shortcut, x)
566		}
567		out := b.addInto(h2, skip)
568		if r.Shortcut != nil {
569			b.release(skip)
570		}
571		if !keepIn {
572			b.release(x)
573		}
574		return out
575	}
576	
577	// attention records the mid block's single-head spatial attention. The three
578	// projections are the three row blocks of to_qkv's [3C, C] weight, read at
579	// offsets; the output projection is its own 1x1. Both run on vae_linear over
580	// the pixel rows, which is what a 1x1 convolution is once the tensor is
581	// transposed out of NCHW.
582	func (b *builder) attention(name string, a *Attention, x tensor) tensor {
583		rows := x.H * x.W
584		dim := x.C
585	
586		h := tensor{off: b.ar.alloc(x.elems()), C: x.C, H: x.H, W: x.W}
587		b.chnorm(name+".norm", false, x, h)
588	
589		seq := tensor{off: b.ar.alloc(rows * dim), C: dim, H: x.H, W: x.W}
590		b.add("to_rows", groups(rows*dim, 256), pushConstants{
591			InOff: h.off, OutOff: seq.off,
592			C: uint32(dim), H: uint32(x.H), W: uint32(x.W),
593		})
594		b.release(h)
595	
596		qkvW, qkvB := b.wOff(name+".qkv.weight"), b.wOff(name+".qkv.bias")
597		proj := func(which int) tensor {
598			out := tensor{off: b.ar.alloc(rows * dim), C: dim, H: x.H, W: x.W}
599			b.label(fmt.Sprintf("linear %d->%d x%d", dim, dim, rows), 2*float64(rows)*float64(dim)*float64(dim))
600			b.add("linear", groups(rows*dim, 64), pushConstants{
601				InOff: seq.off, OutOff: out.off,
602				C: uint32(dim), H: uint32(x.H), W: uint32(x.W), OC: uint32(dim),
603				WOff: qkvW + uint32(which*dim*dim), BOff: qkvB + uint32(which*dim),
604			})
605			return out
606		}
607		q, k, v := proj(0), proj(1), proj(2)
608		b.release(seq)
609	
610		// Transpose K so the score loop reads consecutive keys at consecutive
611		// addresses. The +64 pads the row stride off a multiple of the 4 KB
612		// channel rotation (IDEAS §5.1b).
613		kStride := rows + 64
614		kT := tensor{off: b.ar.alloc(dim * kStride), C: dim, H: 1, W: kStride}
615		b.label(fmt.Sprintf("transpose %dx%d", rows, dim), 0)
616		b.add("transpose", groups(rows*dim, 256), pushConstants{
617			InOff: k.off, OutOff: kT.off,
618			C: uint32(dim), Aux0: uint32(rows), Aux1: uint32(kStride),
619		})
620		b.release(k)
621	
622		ctx := tensor{off: b.ar.alloc(rows * dim), C: dim, H: x.H, W: x.W}
623		// Two passes of q.k plus the weighted sum of v, all over rows x rows.
624		b.label(fmt.Sprintf("attention %d rows x %d", rows, dim),
625			3*2*float64(rows)*float64(rows)*float64(dim))
626		b.add("attention", uint32(rows), pushConstants{
627			InOff: q.off, OutOff: ctx.off, ResOff: kT.off,
628			C:      uint32(dim),
629			Groups: uint32(kStride),
630			Aux0:   uint32(rows), Aux1: math.Float32bits(float32(1 / math.Sqrt(float64(dim)))), Aux2: v.off,
631		})
632		b.release(q, kT, v)
633	
634		outRows := tensor{off: b.ar.alloc(rows * dim), C: dim, H: x.H, W: x.W}
635		b.label(fmt.Sprintf("linear %d->%d x%d", dim, dim, rows), 2*float64(rows)*float64(dim)*float64(dim))
636		b.add("linear", groups(rows*dim, 64), pushConstants{
637			InOff: ctx.off, OutOff: outRows.off,
638			C: uint32(dim), H: uint32(x.H), W: uint32(x.W), OC: uint32(dim),
639			WOff: b.wOff(name + ".proj.weight"), BOff: b.bOff(name + ".proj.bias"),
640		})
641		b.release(ctx)
642	
643		res := tensor{off: b.ar.alloc(x.elems()), C: x.C, H: x.H, W: x.W}
644		// The bias is already in the projection above, so the fused add has none
645		// of its own — and there is no push-constant value that means "unset", so
646		// it is said explicitly.
647		b.add("to_nchw", groups(x.elems(), 256), pushConstants{
648			InOff: outRows.off, OutOff: res.off, ResOff: x.off,
649			C: uint32(x.C), H: uint32(x.H), W: uint32(x.W),
650			Aux0: noBias,
651		})
652		b.release(outRows, x)
653		return res
654	}
655	
656	// upsample is the learned half of an up block's resampling: nearest 2x, then
657	// a 3x3 convolution.
658	func (b *builder) upsample(name string, c *zvae.Conv2D, x tensor) tensor {
659		up := tensor{off: b.ar.alloc(x.C * x.H * 2 * x.W * 2), C: x.C, H: x.H * 2, W: x.W * 2}
660		b.add("upsample2x", groups(up.elems(), 256), pushConstants{
661			InOff: x.off, OutOff: up.off,
662			C: uint32(x.C), H: uint32(x.H), W: uint32(x.W),
663		})
664		b.release(x)
665		out := b.conv(name, c, up)
666		b.release(up)
667		return out
668	}
669	
670	// dupup is the parameter-free shortcut around an up block.
671	func (b *builder) dupup(u *DupUp, x tensor) tensor {
672		out := tensor{off: b.ar.alloc(u.Out * x.H * 2 * x.W * 2), C: u.Out, H: x.H * 2, W: x.W * 2}
673		b.label(fmt.Sprintf("dupup %d->%d @%dx%d", u.In, u.Out, out.H, out.W), 0)
674		b.add("dupup", groups(out.elems(), 256), pushConstants{
675			InOff: x.off, OutOff: out.off,
676			C: uint32(u.In), H: uint32(x.H), W: uint32(x.W), OC: uint32(u.Out),
677			Aux0: uint32(u.FactorT),
678		})
679		return out
680	}
681	
682	// build records the whole decode and returns the output tensor, which is
683	// still unclamped: the clamp to [-1, 1] rides on the readback.
684	func (b *builder) build(d *Decoder, latentH, latentW int) tensor {
685		z := tensor{off: b.ar.alloc(d.PostQuant.InC * latentH * latentW), C: d.PostQuant.InC, H: latentH, W: latentW}
686		x := b.conv("post_quant", &d.PostQuant, z)
687		b.release(z)
688		h := b.conv("conv_in", &d.ConvIn, x)
689		b.release(x)
690		b.mark("conv_in", h)
691	
692		h = b.resblock("mid.r1", &d.Mid.Res1, h, false)
693		h = b.attention("mid.attn", &d.Mid.Attn, h)
694		h = b.resblock("mid.r2", &d.Mid.Res2, h, false)
695		b.mark("mid_block", h)
696	
697		for i := range d.Ups {
698			up := &d.Ups[i]
699			in := h
700			keep := up.Shortcut != nil
701			for j := range up.Resnets {
702				// Only the first resnet reads the block's input, so only it has to
703				// be told to keep it alive.
704				h = b.resblock(fmt.Sprintf("up.%d.r%d", i, j), &up.Resnets[j], h, keep && j == 0)
705			}
706			if up.Up != nil {
707				h = b.upsample(fmt.Sprintf("up.%d.upconv", i), &up.Up.Conv, h)
708			}
709			if up.Shortcut != nil {
710				short := b.dupup(up.Shortcut, in)
711				h = b.addInto(h, short)
712				b.release(short, in)
713			}
714			b.mark(fmt.Sprintf("up_blocks.%d", i), h)
715		}
716	
717		h = b.chnorm("norm_out", true, h, h)
718		b.mark("nonlinearity", h)
719		out := b.conv("conv_out", &d.ConvOut, h)
720		b.release(h)
721		return b.mark("conv_out", out)
722	}
723	
724	// plan records the graph. A nil-pipelined decoder records it purely to size
725	// the arena or count the dispatches.
726	func (g *GPUDecoder) plan(ar *arena, latentH, latentW int, marks bool) (*builder, tensor, error) {
727		b := &builder{e: &g.engine, ar: ar}
728		if marks {
729			b.marks = map[string]tensor{}
730		}
731		out := b.build(g.cpu, latentH, latentW)
732		return b, out, b.err
733	}
734	
735	// MaxStorageBufferBytes is this device's `maxStorageBufferRange`, 4 GiB - 4.
736	// The activation arena is one buffer, so it is also the ceiling on what a
737	// decode can be planned for — see ArenaBytes.
738	const MaxStorageBufferBytes = 4<<30 - 4
739	
740	// ArenaBytes is how much activation memory a decode of this latent would
741	// need, without a device and without loading a weight. It is what sizes the
742	// ceiling Q6's geometry has to respect: the arena is a single storage
743	// buffer, and this device caps one of those at MaxStorageBufferBytes.
744	func ArenaBytes(cpu *Decoder, latentH, latentW int) (int, error) {
745		g := &GPUDecoder{engine: newEngine(), cpu: cpu}
746		n, err := g.planSize(latentH, latentW)
747		if err != nil {
748			return 0, err
749		}
750		return int(n) * 4, nil
751	}
752	
753	// planSize finds how large the activation arena has to be, by recording the
754	// graph with no pipelines bound.
755	func (g *GPUDecoder) planSize(latentH, latentW int) (uint32, error) {
756		saved := g.pipes
757		g.pipes = map[string]*vk.ComputePipeline{}
758		b, _, err := g.plan(&arena{}, latentH, latentW, false)
759		g.pipes = saved
760		if err != nil {
761			return 0, err
762		}
763		return b.ar.high, nil
764	}
765	
766	// Dispatches is the number of GPU dispatches one decode records.
767	func (g *GPUDecoder) Dispatches(latentH, latentW int) (int, error) {
768		saved := g.pipes
769		g.pipes = map[string]*vk.ComputePipeline{}
770		b, _, err := g.plan(&arena{}, latentH, latentW, false)
771		g.pipes = saved
772		if err != nil {
773			return 0, err
774		}
775		return len(b.out), nil
776	}
777	
778	// record builds the graph against the real arena and uploads the latent.
779	func (g *GPUDecoder) record(z *zvae.Tensor, marks bool) (*builder, tensor, error) {
780		if z.N != 1 {
781			return nil, tensor{}, fmt.Errorf("qvae: the GPU decoder takes one latent at a time, got N=%d", z.N)
782		}
783		if z.C != g.cpu.PostQuant.InC {
784			return nil, tensor{}, fmt.Errorf("qvae: latent has %d channels, post_quant_conv takes %d", z.C, g.cpu.PostQuant.InC)
785		}
786		g.arena.reset()
787		b, out, err := g.plan(&g.arena, z.H, z.W, marks)
788		if err != nil {
789			return nil, tensor{}, err
790		}
791		if int(b.ar.high)*4 > g.abuf.Size() {
792			return nil, tensor{}, fmt.Errorf("qvae: graph needs %d MB of activations, arena is %d MB",
793				(int(b.ar.high)*4)>>20, g.abuf.Size()>>20)
794		}
795		// The latent is the arena's first allocation, so it goes in at offset 0.
796		g.abuf.WriteFloat32(z.Data)
797		return b, out, nil
798	}
799	
800	// Decode decodes one denormalized latent, clamped to [-1, 1] like the
801	// reference's. The whole graph is recorded once and submitted in batches.
802	func (g *GPUDecoder) Decode(ctx context.Context, z *zvae.Tensor) (*zvae.Tensor, error) {
803		b, out, err := g.record(z, false)
804		if err != nil {
805			return nil, err
806		}
807		if err := g.runContext(ctx, b.out); err != nil {
808			return nil, err
809		}
810		img := g.read(out)
811		// The clamp is the reference's, and it is free here: the readback is
812		// already walking every element.
813		for i, v := range img.Data {
814			if v > 1 {
815				img.Data[i] = 1
816			} else if v < -1 {
817				img.Data[i] = -1
818			}
819		}
820		return img, nil
821	}
822	
823	// Stages names the graph's marked stages, in order. They are the same names
824	// the CPU decoder's Tap emits, so a stagewise comparison needs no mapping.
825	func (g *GPUDecoder) Stages(latentH, latentW int) ([]string, error) {
826		saved := g.pipes
827		g.pipes = map[string]*vk.ComputePipeline{}
828		b, _, err := g.plan(&arena{}, latentH, latentW, true)
829		g.pipes = saved
830		if err != nil {
831			return nil, err
832		}
833		return b.order, nil
834	}
835	
836	// RunTo re-runs the graph from the start and stops after the named stage,
837	// returning what it produced. A bump-allocated graph overwrites every
838	// intermediate long before it ends, so re-running the prefix is the only way
839	// to see one — the same facility, for the same reason, as zimage/vae's
840	// GPUEncoder.RunTo.
841	func (g *GPUDecoder) RunTo(z *zvae.Tensor, stage string) (*zvae.Tensor, error) {
842		b, _, err := g.record(z, true)
843		if err != nil {
844			return nil, err
845		}
846		t, ok := b.marks[stage]
847		if !ok {
848			return nil, fmt.Errorf("qvae: no stage %q (have %v)", stage, b.order)
849		}
850		stop := 0
851		for i, name := range b.order {
852			if name == stage {
853				stop = b.stops[i]
854				break
855			}
856		}
857		if err := g.run(b.out[:stop]); err != nil {
858			return nil, err
859		}
860		return g.read(t), nil
861	}
862	
863	// ConvInputRange is one convolution's input magnitude, as measured by
864	// running the graph up to it.
865	type ConvInputRange struct {
866		Index  int
867		Kind   string
868		AbsMax float64
869	}
870	
871	// ConvInputRanges reports, for every convolution in the graph, the largest
872	// magnitude in the tensor it reads.
873	//
874	// It answers the one question standing between this decode and z-image's
875	// matrix-core convolution, which took that operator from 3.18 s to 258 ms
876	// and is 69% of this one. That kernel narrows its B operand — the
877	// activation — to fp16 and accumulates in fp32, so what decides whether it
878	// can be pointed at a graph is whether the activations clear 65504. In
879	// z-image's decoder they peak at 497, 132x inside; Q0 measured this model's
880	// intermediates at absmax ~1e5–3e5, which is why the answer is measured
881	// here rather than inherited.
882	//
883	// It reads a tensor back per convolution over a write-combined buffer, so
884	// it is slow by construction and belongs at the reference latent size.
885	func (g *GPUDecoder) ConvInputRanges(z *zvae.Tensor) ([]ConvInputRange, error) {
886		b, _, err := g.record(z, false)
887		if err != nil {
888			return nil, err
889		}
890		var out []ConvInputRange
891		for i := range b.out {
892			if in := b.ins[i]; in.C != 0 {
893				var absMax float64
894				for _, v := range g.abuf.ReadFloat32At(int(in.off), in.elems()) {
895					if a := math.Abs(float64(v)); a > absMax {
896						absMax = a
897					}
898				}
899				out = append(out, ConvInputRange{Index: i, Kind: b.kinds[i], AbsMax: absMax})
900			}
901			if _, err := vk.DispatchMultiTimed(b.out[i:i+1], 1, 1, true); err != nil {
902				return out, fmt.Errorf("qvae: dispatch %d (%s): %w", i, b.kinds[i], err)
903			}
904		}
905		return out, nil
906	}
907	
908	// Stage is one dispatch's identity and cost, as returned by Profile.
909	type Stage struct {
910		Index int
911		Kind  string
912		GPU   time.Duration
913		// Flops is the dispatch's multiply-accumulate count, x2.
914		Flops float64
915	}
916	
917	// Profile runs the graph one dispatch at a time, timing each on the GPU.
918	// Submitting separately costs a fence wait per dispatch, so the total is
919	// above what Decode measures — what it is for is the distribution.
920	func (g *GPUDecoder) Profile(z *zvae.Tensor) ([]Stage, error) {
921		b, _, err := g.record(z, false)
922		if err != nil {
923			return nil, err
924		}
925		stages := make([]Stage, 0, len(b.out))
926		for i, d := range b.out {
927			dur, err := d.Pipeline.DispatchTimed(d.GroupsX, d.GroupsY, 1, 1, d.PushConstants)
928			if err != nil {
929				return stages, fmt.Errorf("qvae: dispatch %d (%s): %w", i, b.kinds[i], err)
930			}
931			stages = append(stages, Stage{Index: i, Kind: b.kinds[i], GPU: dur, Flops: b.flops[i]})
932		}
933		return stages, nil
934	}
