1	// Package vae implements the Z-Image / Flux AutoencoderKL decoder: 16
2	// latent channels to RGB at 8x resolution.
3	//
4	// This is the CPU reference implementation. It exists before the Vulkan one
5	// on purpose: it separates "do I understand the architecture" from "is the
6	// shader right", and once it matches diffusers it becomes the oracle the GPU
7	// port is debugged against. It is written for clarity over speed — a direct
8	// convolution parallelised over output channels, no im2col, no blocking —
9	// because the fast version of this is a compute shader and not a smarter
10	// Go loop.
11	//
12	// Layout is NCHW float32 throughout, matching PyTorch, so a tensor here can
13	// be compared to a reference dump byte for byte with no transpose in the
14	// way.
15	package vae
16	
17	import (
18		"fmt"
19		"runtime"
20		"sync"
21	)
22	
23	// Tensor is a dense NCHW float32 tensor.
24	type Tensor struct {
25		N, C, H, W int
26		Data       []float32
27	}
28	
29	// NewTensor allocates a zeroed tensor.
30	func NewTensor(n, c, h, w int) *Tensor {
31		return &Tensor{N: n, C: c, H: h, W: w, Data: make([]float32, n*c*h*w)}
32	}
33	
34	// Len is the element count.
35	func (t *Tensor) Len() int { return t.N * t.C * t.H * t.W }
36	
37	// Plane returns the h*w slice for one image and channel.
38	func (t *Tensor) Plane(n, c int) []float32 {
39		off := ((n * t.C) + c) * t.H * t.W
40		return t.Data[off : off+t.H*t.W]
41	}
42	
43	// Shape renders the shape the way the reference manifest writes it.
44	func (t *Tensor) Shape() []int { return []int{t.N, t.C, t.H, t.W} }
45	
46	func (t *Tensor) String() string {
47		return fmt.Sprintf("[%d %d %d %d]", t.N, t.C, t.H, t.W)
48	}
49	
50	// parallelFor runs fn over [0,n) across GOMAXPROCS workers. Every heavy loop
51	// here is embarrassingly parallel over output channels, which is both the
52	// outermost loop and the one with no write aliasing between iterations.
53	func parallelFor(n int, fn func(i int)) {
54		workers := runtime.GOMAXPROCS(0)
55		if workers > n {
56			workers = n
57		}
58		if workers <= 1 {
59			for i := 0; i < n; i++ {
60				fn(i)
61			}
62			return
63		}
64		var wg sync.WaitGroup
65		next := make(chan int, n)
66		for i := 0; i < n; i++ {
67			next <- i
68		}
69		close(next)
70		wg.Add(workers)
71		for w := 0; w < workers; w++ {
72			go func() {
73				defer wg.Done()
74				for i := range next {
75					fn(i)
76				}
77			}()
78		}
79		wg.Wait()
80	}
81	
82	// Conv2D is a 2-D convolution with zero padding, weights in PyTorch's
83	// [outC, inC, kh, kw] order.
84	//
85	// Stride and PadEnd exist for the encoder's three downsamplers and are zero
86	// everywhere else. **They are one shape between them, not two knobs**:
87	// diffusers' Downsample2D pads (0, 1, 0, 1) -- nothing on the top and left,
88	// one pixel on the bottom and right -- and then convolves with stride 2 and
89	// no padding of its own. So Pad stays the symmetric padding every other
90	// convolution in this package uses, PadEnd is the extra row and column on the
91	// far side, and a zero in either is the ordinary case.
92	type Conv2D struct {
93		InC, OutC int
94		KH, KW    int
95		Pad       int
96		// PadEnd is extra zero padding on the bottom and right only.
97		PadEnd int
98		// Stride is the step between output pixels; 0 and 1 both mean 1, so that
99		// every Conv2D built before this field existed still means what it did.
100		Stride int
101		Weight []float32 // [OutC][InC][KH][KW]
102		Bias   []float32 // [OutC], may be nil
103	}
104	
105	// stride is Stride with the zero value read as 1.
106	func (c *Conv2D) stride() int {
107		if c.Stride < 1 {
108			return 1
109		}
110		return c.Stride
111	}
112	
113	// OutSize is the spatial size this convolution produces from an input side of
114	// n, which is PyTorch's formula with the two paddings separated.
115	func (c *Conv2D) OutSize(n, k int) int {
116		return (n+2*c.Pad+c.PadEnd-k)/c.stride() + 1
117	}
118	
119	// convTap, when set, is called with every convolution's input before it runs.
120	// It is how TestConvInputsFitFP16 measures the headroom the matrix-core
121	// convolution depends on -- stage 2's "absmax 497 through the whole decoder"
122	// as an assertion rather than as a memory -- without keeping a second copy
123	// of the decoder's graph in the test. Nothing in the library sets it.
124	var convTap func(c *Conv2D, x *Tensor)
125	
126	// Apply runs the convolution. Output is [N, OutC, H, W] for the 3x3 pad-1 and
127	// 1x1 pad-0 cases this decoder uses, both of which preserve spatial size.
128	func (c *Conv2D) Apply(x *Tensor) (*Tensor, error) {
129		if convTap != nil {
130			convTap(c, x)
131		}
132		if x.C != c.InC {
133			return nil, fmt.Errorf("vae: conv expects %d input channels, got %d", c.InC, x.C)
134		}
135		stride := c.stride()
136		outH := c.OutSize(x.H, c.KH)
137		outW := c.OutSize(x.W, c.KW)
138		if outH <= 0 || outW <= 0 {
139			return nil, fmt.Errorf("vae: conv on %s with kernel %dx%d pad %d leaves nothing", x, c.KH, c.KW, c.Pad)
140		}
141		out := NewTensor(x.N, c.OutC, outH, outW)
142	
143		for n := 0; n < x.N; n++ {
144			parallelFor(c.OutC, func(oc int) {
145				dst := out.Plane(n, oc)
146				var bias float32
147				if c.Bias != nil {
148					bias = c.Bias[oc]
149				}
150				for i := range dst {
151					dst[i] = bias
152				}
153				// Accumulate one (input channel, kernel tap) plane at a time.
154				// Holding the tap fixed makes the inner loop a contiguous
155				// strided add over a whole output row.
156				for ic := 0; ic < c.InC; ic++ {
157					src := x.Plane(n, ic)
158					wbase := ((oc * c.InC) + ic) * c.KH * c.KW
159					for kh := 0; kh < c.KH; kh++ {
160						for kw := 0; kw < c.KW; kw++ {
161							wv := c.Weight[wbase+kh*c.KW+kw]
162							if wv == 0 {
163								continue
164							}
165							for oh := 0; oh < outH; oh++ {
166								ih := oh*stride + kh - c.Pad
167								if ih < 0 || ih >= x.H {
168									continue
169								}
170								// Clip the output-column range to where the
171								// input column is in bounds, so the inner loop
172								// carries no branch. With a stride the two
173								// bounds are the same inequality divided by it:
174								// lo rounds up and hi rounds down.
175								lo, hi := 0, outW
176								if v := ceilDiv(c.Pad-kw, stride); v > lo {
177									lo = v
178								}
179								if v := floorDiv(x.W-1+c.Pad-kw, stride) + 1; v < hi {
180									hi = v
181								}
182								if lo >= hi {
183									continue
184								}
185								drow := dst[oh*outW : (oh+1)*outW]
186								srow := src[ih*x.W : (ih+1)*x.W]
187								base := kw - c.Pad
188								for ow := lo; ow < hi; ow++ {
189									drow[ow] += wv * srow[ow*stride+base]
190								}
191							}
192						}
193					}
194				}
195			})
196		}
197		return out, nil
198	}
199	
200	// GroupNorm normalises over (C/groups, H, W) per group, then scales and
201	// shifts per channel. The decoder uses 32 groups and eps 1e-6 everywhere.
202	type GroupNorm struct {
203		Groups int
204		Eps    float64
205		Weight []float32 // [C]
206		Bias   []float32 // [C]
207	}
208	
209	// ApplyInPlace normalises x and returns it, so a caller can chain without
210	// allocating a tensor per norm.
211	func (g *GroupNorm) ApplyInPlace(x *Tensor) (*Tensor, error) {
212		if x.C%g.Groups != 0 {
213			return nil, fmt.Errorf("vae: %d channels do not divide into %d groups", x.C, g.Groups)
214		}
215		perGroup := x.C / g.Groups
216		hw := x.H * x.W
217		for n := 0; n < x.N; n++ {
218			parallelFor(g.Groups, func(gi int) {
219				c0 := gi * perGroup
220				// Mean and variance in float64: a group here is up to 512*128*128
221				// elements and a float32 running sum loses the low bits long
222				// before the end of that.
223				var sum, sumSq float64
224				for c := c0; c < c0+perGroup; c++ {
225					p := x.Plane(n, c)
226					for _, v := range p {
227						sum += float64(v)
228						sumSq += float64(v) * float64(v)
229					}
230				}
231				count := float64(perGroup * hw)
232				mean := sum / count
233				variance := sumSq/count - mean*mean
234				if variance < 0 {
235					variance = 0
236				}
237				inv := float32(1 / sqrt64(variance+g.Eps))
238				fmean := float32(mean)
239				for c := c0; c < c0+perGroup; c++ {
240					p := x.Plane(n, c)
241					w, b := g.Weight[c], g.Bias[c]
242					scale := w * inv
243					shift := b - fmean*scale
244					for i, v := range p {
245						p[i] = v*scale + shift
246					}
247				}
248			})
249		}
250		return x, nil
251	}
252	
253	// SiLUInPlace applies x * sigmoid(x).
254	func SiLUInPlace(x *Tensor) *Tensor {
255		parallelFor(x.N*x.C, func(p int) {
256			plane := x.Plane(p/x.C, p%x.C)
257			for i, v := range plane {
258				plane[i] = v / (1 + exp32(-v))
259			}
260		})
261		return x
262	}
263	
264	// UpsampleNearest2x doubles H and W by pixel replication, which is what
265	// diffusers' Upsample2D does before its convolution.
266	func UpsampleNearest2x(x *Tensor) *Tensor {
267		out := NewTensor(x.N, x.C, x.H*2, x.W*2)
268		for n := 0; n < x.N; n++ {
269			parallelFor(x.C, func(c int) {
270				src, dst := x.Plane(n, c), out.Plane(n, c)
271				for h := 0; h < x.H; h++ {
272					srow := src[h*x.W : (h+1)*x.W]
273					for _, dh := range [2]int{h * 2, h*2 + 1} {
274						drow := dst[dh*out.W : (dh+1)*out.W]
275						for w, v := range srow {
276							drow[w*2] = v
277							drow[w*2+1] = v
278						}
279					}
280				}
281			})
282		}
283		return out
284	}
285	
286	// AddInPlace computes a += b.
287	func AddInPlace(a, b *Tensor) (*Tensor, error) {
288		if a.Len() != b.Len() {
289			return nil, fmt.Errorf("vae: cannot add %s to %s", b, a)
290		}
291		parallelFor(a.N*a.C, func(p int) {
292			ap, bp := a.Plane(p/a.C, p%a.C), b.Plane(p/a.C, p%a.C)
293			for i := range ap {
294				ap[i] += bp[i]
295			}
296		})
297		return a, nil
298	}
299	
300	// Subsample2x keeps the pixel at (2h+1, 2w+1) of every 2x2 block, halving H
301	// and W. It is the second half of the device's stride-2 convolution: the
302	// filter runs at stride 1 with symmetric padding and this throws three
303	// pixels in four away. TestStrideTwoIsStrideOneSubsampled is why that offset
304	// and not the other, and builder.downsample is what it costs.
305	func Subsample2x(x *Tensor) *Tensor {
306		out := NewTensor(x.N, x.C, x.H/2, x.W/2)
307		for n := 0; n < x.N; n++ {
308			parallelFor(x.C, func(c int) {
309				src, dst := x.Plane(n, c), out.Plane(n, c)
310				for h := 0; h < out.H; h++ {
311					srow := src[(h*2+1)*x.W:]
312					drow := dst[h*out.W : (h+1)*out.W]
313					for w := range drow {
314						drow[w] = srow[w*2+1]
315					}
316				}
317			})
318		}
319		return out
320	}
