1	package vae
2	
3	import (
4		"context"
5		"fmt"
6	
7		"strix-halo-vulkan/shaders"
8		"strix-halo-vulkan/vk"
9		zvae "strix-halo-vulkan/zimage/vae"
10	)
11	
12	// The encoder on the device — IMAGE.md Q8, the stage Q5g deferred.
13	//
14	// Nothing t2i serves needs an encoder, which is why the decoder went to the
15	// GPU alone and this waited for edits. An edit needs it per request and per
16	// reference image: the CPU encoder is the oracle and costs minutes at a
17	// served condition size, which is the same argument that moved the decoder.
18	//
19	// It is a small file because the encoder is the decoder's graph read
20	// backwards over the same kernels. Two things differ and only one of them is
21	// new:
22	//
23	//   - **the stride-2 downsampler is not a new kernel**, and it is not even a
24	//     new idea: z-image's encoder found that a 3x3 stride-2 convolution with
25	//     diffusers' (0, 1, 0, 1) padding computes exactly what the stride-1
26	//     pad-1 form computes at the *odd* pixels, so it runs the ordinary
27	//     convolution and throws three pixels in four away. Qwen's downsampler
28	//     has the identical shape, and vae_downsample2x.comp — which keeps
29	//     (2h+1, 2w+1) — is reused unmodified. The discarded three quarters are
30	//     the price of not writing a second convolution;
31	//   - **AvgDown3D is new** (qvae_avgdown.comp), the mirror of the decoder's
32	//     DupUp: space folded into channels and the group averaged, with a
33	//     temporal factor that at T = 1 still averages in a zero frame and still
34	//     divides by the full group.
35	//
36	// The mid block is **768** channels wide here against the decoder's 1152 —
37	// base_dim 96 against decoder_base_dim 144 — so the attention kernel is a
38	// different build of the same source, and the width is checked at
39	// construction for the same reason the decoder checks its own.
40	
41	// encoderShaderSet is the encoder's pipelines. Every one of them is the
42	// decoder's or z-image's except qvae_avgdown; the up-only kernels
43	// (upsample2x, dupup) are not built here.
44	var encoderShaderSet = map[string][]byte{
45		"conv2d":       shaders.VAEConv2D,
46		"add":          shaders.VAEAdd,
47		"downsample2x": shaders.VAEDownsample2x,
48		"to_rows":      shaders.VAENCHWToRows,
49		"to_nchw":      shaders.VAERowsToNCHWAdd,
50		"linear":       shaders.VAELinear,
51		"transpose":    shaders.VAETranspose,
52		"attention":    shaders.VAEAttentionDim768,
53		"chnorm":       shaders.QVAEChannelNorm,
54		"avgdown":      shaders.QVAEAvgDown,
55	}
56	
57	// encMidDim is the channel width encoderShaderSet's attention build expects.
58	const encMidDim = 768
59	
60	// GPUEncoder runs the encode graph on a Vulkan device.
61	type GPUEncoder struct {
62		engine
63		cpu *Encoder
64	}
65	
66	// NewGPUEncoder uploads a loaded encoder's weights, builds its pipelines and
67	// sizes the activation arena for an imgH x imgW image — the largest the
68	// returned encoder will accept, since the arena is allocated once.
69	func NewGPUEncoder(dev *vk.Device, cpu *Encoder, imgH, imgW int) (*GPUEncoder, error) {
70		if got := cpu.Mid.Attn.QKV.InC; got != encMidDim {
71			return nil, fmt.Errorf("qvae: encoder mid block is %d channels, the attention kernel is built for %d", got, encMidDim)
72		}
73		g := &GPUEncoder{engine: newEngine(), cpu: cpu}
74		g.flattenWeights()
75	
76		need, err := g.planSize(imgH, imgW)
77		if err != nil {
78			g.Destroy()
79			return nil, err
80		}
81		if err := g.stage(dev, encoderShaderSet, need); err != nil {
82			g.Destroy()
83			return nil, err
84		}
85		return g, nil
86	}
87	
88	// Destroy releases every Vulkan object.
89	func (g *GPUEncoder) Destroy() { g.destroy() }
90	
91	// flattenWeights copies every weight the graph reads into one arena, in the
92	// order the graph reads them.
93	func (g *GPUEncoder) flattenWeights() {
94		w := g.weights
95		conv := func(name string, c *zvae.Conv2D) {
96			w.put(name+".weight", c.Weight)
97			if c.Bias != nil {
98				w.put(name+".bias", c.Bias)
99			}
100		}
101		norm := func(name string, n *ChannelNorm) { w.put(name+".gamma", n.Gamma) }
102		res := func(name string, r *ResBlock) {
103			norm(name+".norm1", &r.Norm1)
104			conv(name+".conv1", &r.Conv1)
105			norm(name+".norm2", &r.Norm2)
106			conv(name+".conv2", &r.Conv2)
107			if r.Shortcut != nil {
108				conv(name+".shortcut", r.Shortcut)
109			}
110		}
111	
112		e := g.cpu
113		conv("conv_in", &e.ConvIn)
114		for i := range e.Downs {
115			down := &e.Downs[i]
116			for j := range down.Resnets {
117				res(fmt.Sprintf("down.%d.r%d", i, j), &down.Resnets[j])
118			}
119			if down.Down != nil {
120				conv(fmt.Sprintf("down.%d.downconv", i), &down.Down.Conv)
121			}
122		}
123		res("mid.r1", &e.Mid.Res1)
124		norm("mid.attn.norm", &e.Mid.Attn.Norm)
125		conv("mid.attn.qkv", &e.Mid.Attn.QKV)
126		conv("mid.attn.proj", &e.Mid.Attn.Proj)
127		res("mid.r2", &e.Mid.Res2)
128		norm("norm_out", &e.NormOut)
129		conv("conv_out", &e.ConvOut)
130		conv("quant", &e.Quant)
131	}
132	
133	// downsample records one stride-2 convolution as a stride-1 one followed by
134	// the subsampling kernel, which is z-image's identity on Qwen's filter: a
135	// 3x3 stride-2 convolution over a (0, 1, 0, 1)-padded input computes exactly
136	// what the 3x3 stride-1 pad-1 form computes at the odd pixels.
137	//
138	// It costs four times the arithmetic of a real stride-2 kernel and saves a
139	// second convolution shader. Whether that trade is still right is a Q9
140	// question, not this stage's: the same sentence is in zimage/vae, with the
141	// same reasoning and the same numbers waiting to be measured.
142	func (b *builder) downsample(name string, c *zvae.Conv2D, x tensor) tensor {
143		if c.Stride != 2 || c.KH != 3 || c.KW != 3 || c.Pad != 0 || c.PadEnd != 1 {
144			b.err = fmt.Errorf("qvae: downsample %s is %dx%d stride %d pad %d/%d; the subsampling identity is for a 3x3 stride-2 (0,1,0,1) filter",
145				name, c.KH, c.KW, c.Stride, c.Pad, c.PadEnd)
146			return x
147		}
148		// The same weights read as an ordinary symmetric-pad convolution.
149		stride1 := *c
150		stride1.Pad, stride1.PadEnd, stride1.Stride = 1, 0, 1
151		h := b.conv(name, &stride1, x)
152	
153		out := tensor{off: b.ar.alloc(h.C * (h.H / 2) * (h.W / 2)), C: h.C, H: h.H / 2, W: h.W / 2}
154		b.label(fmt.Sprintf("downsample %d @%dx%d", h.C, h.H, h.W), 0)
155		b.add("downsample2x", groups(out.elems(), 256), pushConstants{
156			InOff: h.off, OutOff: out.off,
157			C: uint32(h.C), H: uint32(h.H), W: uint32(h.W),
158		})
159		b.release(h)
160		return out
161	}
162	
163	// avgdown is the parameter-free shortcut around a down block.
164	func (b *builder) avgdown(a *AvgDown, x tensor) tensor {
165		fs := a.FactorS
166		out := tensor{off: b.ar.alloc(a.Out * (x.H / fs) * (x.W / fs)), C: a.Out, H: x.H / fs, W: x.W / fs}
167		b.label(fmt.Sprintf("avgdown %d->%d @%dx%d", a.In, a.Out, out.H, out.W), 0)
168		b.add("avgdown", groups(out.elems(), 256), pushConstants{
169			InOff: x.off, OutOff: out.off,
170			C: uint32(a.In), H: uint32(x.H), W: uint32(x.W), OC: uint32(a.Out),
171			Aux0: uint32(a.FactorT), Aux1: uint32(fs),
172		})
173		return out
174	}
175	
176	// buildEncode records the whole encode and returns the quantized output —
177	// [2z, h, w], mean then logvar. Encode keeps the mean half, which is the
178	// posterior mode and is contiguous in NCHW.
179	func (b *builder) buildEncode(e *Encoder, imgH, imgW int) tensor {
180		img := tensor{off: b.ar.alloc(e.ConvIn.InC * imgH * imgW), C: e.ConvIn.InC, H: imgH, W: imgW}
181		h := b.conv("conv_in", &e.ConvIn, img)
182		b.release(img)
183		b.mark("conv_in", h)
184	
185		for i := range e.Downs {
186			d := &e.Downs[i]
187			in := h
188			// The shortcut reads the block's *input*, so it is recorded before
189			// the resnets overwrite it and the input is kept alive until it has.
190			short := b.avgdown(&d.Shortcut, in)
191			for j := range d.Resnets {
192				h = b.resblock(fmt.Sprintf("down.%d.r%d", i, j), &d.Resnets[j], h, j == 0)
193			}
194			if d.Down != nil {
195				h = b.downsample(fmt.Sprintf("down.%d.downconv", i), &d.Down.Conv, h)
196			}
197			h = b.addInto(h, short)
198			b.release(short, in)
199			b.mark(fmt.Sprintf("down_blocks.%d", i), h)
200		}
201	
202		h = b.resblock("mid.r1", &e.Mid.Res1, h, false)
203		h = b.attention("mid.attn", &e.Mid.Attn, h)
204		h = b.resblock("mid.r2", &e.Mid.Res2, h, false)
205		b.mark("mid_block", h)
206	
207		h = b.chnorm("norm_out", true, h, h)
208		b.mark("nonlinearity", h)
209		out := b.conv("conv_out", &e.ConvOut, h)
210		b.release(h)
211		b.mark("conv_out", out)
212		q := b.conv("quant", &e.Quant, out)
213		b.release(out)
214		return b.mark("quant", q)
215	}
216	
217	// plan records the graph. A pipeline-less encoder records it purely to size
218	// the arena or count the dispatches.
219	func (g *GPUEncoder) plan(ar *arena, imgH, imgW int, marks bool) (*builder, tensor, error) {
220		b := &builder{e: &g.engine, ar: ar}
221		if marks {
222			b.marks = map[string]tensor{}
223		}
224		out := b.buildEncode(g.cpu, imgH, imgW)
225		return b, out, b.err
226	}
227	
228	func (g *GPUEncoder) planSize(imgH, imgW int) (uint32, error) {
229		saved := g.pipes
230		g.pipes = map[string]*vk.ComputePipeline{}
231		b, _, err := g.plan(&arena{}, imgH, imgW, false)
232		g.pipes = saved
233		if err != nil {
234			return 0, err
235		}
236		return b.ar.high, nil
237	}
238	
239	// EncoderArenaBytes is how much activation memory an encode of this image
240	// would need, without a device and without loading a weight — the encoder's
241	// half of the ceiling arithmetic ArenaBytes does for the decoder.
242	func EncoderArenaBytes(cpu *Encoder, imgH, imgW int) (int, error) {
243		g := &GPUEncoder{engine: newEngine(), cpu: cpu}
244		n, err := g.planSize(imgH, imgW)
245		if err != nil {
246			return 0, err
247		}
248		return int(n) * 4, nil
249	}
250	
251	// Dispatches is the number of GPU dispatches one encode records.
252	func (g *GPUEncoder) Dispatches(imgH, imgW int) (int, error) {
253		saved := g.pipes
254		g.pipes = map[string]*vk.ComputePipeline{}
255		b, _, err := g.plan(&arena{}, imgH, imgW, false)
256		g.pipes = saved
257		if err != nil {
258			return 0, err
259		}
260		return len(b.out), nil
261	}
262	
263	// record builds the graph against the real arena and uploads the image.
264	func (g *GPUEncoder) record(img *zvae.Tensor, marks bool) (*builder, tensor, error) {
265		if img.N != 1 {
266			return nil, tensor{}, fmt.Errorf("qvae: the GPU encoder takes one image at a time, got N=%d", img.N)
267		}
268		if img.C != g.cpu.ConvIn.InC {
269			return nil, tensor{}, fmt.Errorf("qvae: image has %d channels, conv_in takes %d", img.C, g.cpu.ConvIn.InC)
270		}
271		g.arena.reset()
272		b, out, err := g.plan(&g.arena, img.H, img.W, marks)
273		if err != nil {
274			return nil, tensor{}, err
275		}
276		if int(b.ar.high)*4 > g.abuf.Size() {
277			return nil, tensor{}, fmt.Errorf("qvae: graph needs %d MB of activations, arena is %d MB",
278				(int(b.ar.high)*4)>>20, g.abuf.Size()>>20)
279		}
280		// The image is the arena's first allocation, so it goes in at offset 0.
281		g.abuf.WriteFloat32(img.Data)
282		return b, out, nil
283	}
284	
285	// Encode returns the posterior mode of one image in [-1, 1], which is the
286	// mean half of the quantized output and the only half an edit ever reads
287	// (IMAGE.md decision 3). The latents come back *raw* — Config.Normalize maps
288	// them into the DiT's space, exactly as the CPU encoder's caller does it.
289	func (g *GPUEncoder) Encode(ctx context.Context, img *zvae.Tensor) (*zvae.Tensor, error) {
290		b, out, err := g.record(img, false)
291		if err != nil {
292			return nil, err
293		}
294		if err := g.runContext(ctx, b.out); err != nil {
295			return nil, err
296		}
297		return g.read(tensor{off: out.off, C: out.C / 2, H: out.H, W: out.W}), nil
298	}
299	
300	// Stages names the graph's marked stages, in order. They are the names the
301	// CPU encoder's Tap emits, so a stagewise comparison needs no mapping.
302	func (g *GPUEncoder) Stages(imgH, imgW int) ([]string, error) {
303		saved := g.pipes
304		g.pipes = map[string]*vk.ComputePipeline{}
305		b, _, err := g.plan(&arena{}, imgH, imgW, true)
306		g.pipes = saved
307		if err != nil {
308			return nil, err
309		}
310		return b.order, nil
311	}
312	
313	// RunTo re-runs the graph from the start and stops after the named stage,
314	// returning what it produced. A bump-allocated graph overwrites every
315	// intermediate long before it ends, so re-running the prefix is the only way
316	// to see one.
317	func (g *GPUEncoder) RunTo(img *zvae.Tensor, stage string) (*zvae.Tensor, error) {
318		b, _, err := g.record(img, true)
319		if err != nil {
320			return nil, err
321		}
322		t, ok := b.marks[stage]
323		if !ok {
324			return nil, fmt.Errorf("qvae: no stage %q in the encode graph", stage)
325		}
326		stop := 0
327		for i, name := range b.order {
328			if name == stage {
329				stop = b.stops[i]
330				break
331			}
332		}
333		if err := g.run(b.out[:stop]); err != nil {
334			return nil, err
335		}
336		return g.read(t), nil
337	}
