1	package vae
2	
3	import (
4		"fmt"
5		"math"
6		"sort"
7		"testing"
8		"time"
9	
10		"strix-halo-vulkan/vk"
11		zvae "strix-halo-vulkan/zimage/vae"
12	)
13	
14	const strixHaloDeviceID = 0x1586
15	
16	func newTestDevice(t *testing.T) (*vk.Device, func()) {
17		t.Helper()
18		inst, err := vk.NewInstance("qi21-vae-test")
19		if err != nil {
20			t.Skipf("no Vulkan instance: %v", err)
21		}
22		devices, err := inst.PhysicalDevices()
23		if err != nil || len(devices) == 0 {
24			inst.Destroy()
25			t.Skipf("no Vulkan devices: %v", err)
26		}
27		phys := &devices[0]
28		for i := range devices {
29			if devices[i].DeviceID == strixHaloDeviceID {
30				phys = &devices[i]
31				break
32			}
33		}
34		qf, err := phys.ComputeQueueFamily()
35		if err != nil {
36			inst.Destroy()
37			t.Skipf("no compute queue: %v", err)
38		}
39		dev, err := vk.NewDevice(phys, qf, vk.DeviceFeatures{})
40		if err != nil {
41			inst.Destroy()
42			t.Skipf("no device: %v", err)
43		}
44		t.Logf("device: %s", phys.Name)
45		return dev, func() { dev.Destroy(); inst.Destroy() }
46	}
47	
48	// loadCPU loads the config and the CPU decoder, or skips.
49	func loadCPU(t *testing.T) (*Config, *Decoder) {
50		t.Helper()
51		cfg, err := LoadConfig(vaeDir)
52		if err != nil {
53			t.Skipf("no VAE checkpoint at %s (%v)", vaeDir, err)
54		}
55		dec, err := LoadDecoder(vaeDir, cfg)
56		if err != nil {
57			t.Fatal(err)
58		}
59		return cfg, dec
60	}
61	
62	// loadGPU loads the decoder and builds its device graph for one latent size.
63	//
64	// The cleanup is registered rather than deferred by the caller, and the
65	// device's teardown has to be registered the same way and *first*: cleanups
66	// run last-in-first-out and after every deferred call in the test body, so a
67	// deferred dev.Destroy() would free the device out from under these
68	// pipelines and the shim would segfault destroying them.
69	func loadGPU(t *testing.T, dev *vk.Device, h, w int) (*Config, *Decoder, *GPUDecoder) {
70		t.Helper()
71		cfg, dec := loadCPU(t)
72		g, err := NewGPUDecoder(dev, dec, h, w)
73		if err != nil {
74			t.Fatal(err)
75		}
76		t.Cleanup(g.Destroy)
77		return cfg, dec, g
78	}
79	
80	// TestGPUDecoderStages walks the device graph stage by stage against the same
81	// dump the CPU decoder is gated on — conv_in, the mid block, every up block,
82	// the fused tail norm, conv_out and the clamped image — for both of the
83	// dump's cases. The bounds are vae_test.go's, unchanged: this path is fp32
84	// throughout, so a summation-order difference is all that separates it from
85	// the CPU port, and a structural mistake shows at rel >= 1e-1 on every one
86	// of these stages.
87	func TestGPUDecoderStages(t *testing.T) {
88		m := loadManifest(t)
89		dev, done := newTestDevice(t)
90		t.Cleanup(done)
91	
92		for label, c := range m.Cases {
93			lh, lw := c.Latent[len(c.Latent)-2], c.Latent[len(c.Latent)-1]
94			t.Run(label, func(t *testing.T) {
95				cfg, _, g := loadGPU(t, dev, lh, lw)
96				n, err := g.Dispatches(lh, lw)
97				if err != nil {
98					t.Fatal(err)
99				}
100				t.Logf("%s: %d dispatches, %d MB activations, %d MB weights",
101					label, n, g.ActivationBytes()>>20, g.WeightBytes()>>20)
102	
103				z := loadRef(t, m, label+"_z_norm")
104				cfg.Denormalize(z)
105	
106				stages, err := g.Stages(lh, lw)
107				if err != nil {
108					t.Fatal(err)
109				}
110				for _, name := range stages {
111					got, err := g.RunTo(z, name)
112					if err != nil {
113						t.Fatal(err)
114					}
115					compare(t, label+"_dec_"+name, got, loadRef(t, m, label+"_dec_"+name))
116				}
117	
118				img, err := g.Decode(t.Context(), z)
119				if err != nil {
120					t.Fatal(err)
121				}
122				compare(t, label+"_decoded", img, loadRef(t, m, label+"_decoded"))
123			})
124		}
125	}
126	
127	// TestGPUDecoderMatchesCPU is the same decode on both paths, end to end. It
128	// is the tighter instrument of the two: the dump carries the reference's own
129	// fp32 noise, while this isolates what the device graph does differently
130	// from the Go one it was ported from.
131	func TestGPUDecoderMatchesCPU(t *testing.T) {
132		m := loadManifest(t)
133		dev, done := newTestDevice(t)
134		t.Cleanup(done)
135	
136		c, ok := m.Cases["s256"]
137		if !ok {
138			t.Skip("reference has no s256 case")
139		}
140		lh, lw := c.Latent[len(c.Latent)-2], c.Latent[len(c.Latent)-1]
141		cfg, dec, g := loadGPU(t, dev, lh, lw)
142	
143		z := loadRef(t, m, "s256_z_norm")
144		cfg.Denormalize(z)
145	
146		want, err := dec.Decode(z)
147		if err != nil {
148			t.Fatal(err)
149		}
150		got, err := g.Decode(t.Context(), z)
151		if err != nil {
152			t.Fatal(err)
153		}
154		// Named to land on tolFor's loose bound, and for the reason that bound
155		// exists: this comparison is downstream of the tail norm, where the model
156		// rescales O(1e4) activations to O(1) and any summation-order difference
157		// upstream surfaces elementwise. The number to read is the max abs, in
158		// [-1, 1] — it comes out below the CPU port's own distance from the dump.
159		compare(t, "s256_gpu_vs_cpu_decoded", got, want)
160	}
161	
162	// TestGPUDecoderNegativeControl breaks the one piece of the graph that is
163	// neither z-image's nor obvious — the up blocks' parameter-free shortcut,
164	// whose channel mapping depends on a temporal factor that no longer has an
165	// axis — and checks the bound catches it. Without it, "the DupUp layout is
166	// right" rests on a stage comparison that could have been passing for the
167	// wrong reason.
168	func TestGPUDecoderNegativeControl(t *testing.T) {
169		m := loadManifest(t)
170		dev, done := newTestDevice(t)
171		t.Cleanup(done)
172	
173		c, ok := m.Cases["s256"]
174		if !ok {
175			t.Skip("reference has no s256 case")
176		}
177		lh, lw := c.Latent[len(c.Latent)-2], c.Latent[len(c.Latent)-1]
178		cfg, dec := loadCPU(t)
179	
180		// Every temporal factor set to 1: the spatial duplication is unchanged
181		// and only which source channel feeds an output pixel moves.
182		for i := range dec.Ups {
183			if dec.Ups[i].Shortcut != nil {
184				dec.Ups[i].Shortcut.FactorT = 1
185			}
186		}
187		bad, err := NewGPUDecoder(dev, dec, lh, lw)
188		if err != nil {
189			t.Fatal(err)
190		}
191		t.Cleanup(bad.Destroy)
192	
193		z := loadRef(t, m, "s256_z_norm")
194		cfg.Denormalize(z)
195		got, err := bad.Decode(t.Context(), z)
196		if err != nil {
197			t.Fatal(err)
198		}
199		want := loadRef(t, m, "s256_decoded")
200		var rel float64
201		for i := range want.Data {
202			d := math.Abs(float64(got.Data[i]) - float64(want.Data[i]))
203			if r := d / math.Max(math.Abs(float64(want.Data[i])), 1e-3); r > rel {
204				rel = r
205			}
206		}
207		if rel <= normTol {
208			t.Fatalf("temporal factor 1 everywhere still decodes at rel %.3g, inside the %.0e bound", rel, normTol)
209		}
210		t.Logf("negative control (FactorT=1): rel %.3g, %.0fx the bound", rel, rel/normTol)
211	}
212	
213	// TestGPUDecodeTiming is the wall clock a served image pays downstream of the
214	// DiT, at the two sizes Q6 has to choose between. Two runs, per the project's
215	// convention; the first also pays the arena's first touch.
216	func TestGPUDecodeTiming(t *testing.T) {
217		if testing.Short() {
218			t.Skip("timing runs the full-size graph")
219		}
220		dev, done := newTestDevice(t)
221		t.Cleanup(done)
222	
223		for _, side := range []int{256, 1024} {
224			lat := side / 16
225			t.Run(fmt.Sprintf("%dx%d", side, side), func(t *testing.T) {
226				_, _, g := loadGPU(t, dev, lat, lat)
227				n, err := g.Dispatches(lat, lat)
228				if err != nil {
229					t.Fatal(err)
230				}
231				z := zvae.NewTensor(1, 64, lat, lat)
232				for i := range z.Data {
233					z.Data[i] = float32(math.Sin(float64(i)*0.001)) * 0.5
234				}
235				for run := 0; run < 2; run++ {
236					start := time.Now()
237					if _, err := g.Decode(t.Context(), z); err != nil {
238						t.Fatal(err)
239					}
240					t.Logf("run %d: %v (%d dispatches, %d MB activations)",
241						run, time.Since(start).Round(time.Millisecond), n, g.ActivationBytes()>>20)
242				}
243			})
244		}
245	}
246	
247	// TestGPUDecodeProfile attributes the decode by kind, which is what says
248	// whether the next percent is worth taking and where. It is not a gate.
249	func TestGPUDecodeProfile(t *testing.T) {
250		if testing.Short() {
251			t.Skip("profiling runs the full-size graph one dispatch at a time")
252		}
253		dev, done := newTestDevice(t)
254		t.Cleanup(done)
255	
256		const lat = 64 // a 1024x1024 image
257		_, _, g := loadGPU(t, dev, lat, lat)
258		z := zvae.NewTensor(1, 64, lat, lat)
259		for i := range z.Data {
260			z.Data[i] = float32(math.Sin(float64(i)*0.001)) * 0.5
261		}
262		stages, err := g.Profile(z)
263		if err != nil {
264			t.Fatal(err)
265		}
266	
267		type agg struct {
268			d     time.Duration
269			flops float64
270			n     int
271		}
272		byOp := map[string]*agg{}
273		var total time.Duration
274		for _, s := range stages {
275			op := s.Kind
276			if i := indexByte(op, ' '); i > 0 {
277				op = op[:i]
278			}
279			a := byOp[op]
280			if a == nil {
281				a = &agg{}
282				byOp[op] = a
283			}
284			a.d += s.GPU
285			a.flops += s.Flops
286			a.n++
287			total += s.GPU
288		}
289		ops := make([]string, 0, len(byOp))
290		for op := range byOp {
291			ops = append(ops, op)
292		}
293		sort.Slice(ops, func(i, j int) bool { return byOp[ops[i]].d > byOp[ops[j]].d })
294		t.Logf("1024x1024 decode: %v over %d dispatches", total.Round(time.Millisecond), len(stages))
295		for _, op := range ops {
296			a := byOp[op]
297			tf := a.flops / a.d.Seconds() / 1e12
298			t.Logf("  %-12s %6d x  %9v  %5.1f%%  %6.1f TFLOP/s",
299				op, a.n, a.d.Round(time.Millisecond), 100*float64(a.d)/float64(total), tf)
300		}
301		sort.Slice(stages, func(i, j int) bool { return stages[i].GPU > stages[j].GPU })
302		t.Log("  slowest dispatches:")
303		for _, s := range stages[:min(8, len(stages))] {
304			t.Logf("    %-44s %9v", s.Kind, s.GPU.Round(time.Millisecond))
305		}
306	}
307	
308	func indexByte(s string, b byte) int {
309		for i := 0; i < len(s); i++ {
310			if s[i] == b {
311				return i
312			}
313		}
314		return -1
315	}
316	
317	// TestConvInputRanges measures what a matrix-core convolution would have to
318	// narrow. z-image's decoder peaks at 497 and its whole graph moved to fp16
319	// operands on that number; IMAGE.md's Q0 finding says this model does not,
320	// and this is where "does not" becomes a list of which convolutions.
321	func TestConvInputRanges(t *testing.T) {
322		if testing.Short() {
323			t.Skip("reads a tensor back per convolution")
324		}
325		m := loadManifest(t)
326		dev, done := newTestDevice(t)
327		t.Cleanup(done)
328	
329		c, ok := m.Cases["s256"]
330		if !ok {
331			t.Skip("reference has no s256 case")
332		}
333		lh, lw := c.Latent[len(c.Latent)-2], c.Latent[len(c.Latent)-1]
334		cfg, _, g := loadGPU(t, dev, lh, lw)
335	
336		z := loadRef(t, m, "s256_z_norm")
337		cfg.Denormalize(z)
338		ranges, err := g.ConvInputRanges(z)
339		if err != nil {
340			t.Fatal(err)
341		}
342	
343		// fp16's largest finite value. A narrowed operand at or above it is an
344		// infinity, and one infinity in a fragment makes the whole output tile a
345		// NaN.
346		const fp16Max = 65504.0
347		var over int
348		for _, r := range ranges {
349			flag := ""
350			if r.AbsMax >= fp16Max {
351				flag = "  OVER fp16"
352				over++
353			}
354			t.Logf("%-38s absmax %10.4g%s", r.Kind, r.AbsMax, flag)
355		}
356		t.Logf("%d of %d convolutions exceed fp16", over, len(ranges))
357	}
358	
359	// TestArenaCeiling is the geometry ceiling Q6 has to serve under. The
360	// activation arena is a single storage buffer and this device caps one at
361	// 4 GiB - 4, so "how large an image can this decoder decode" is a question
362	// with an exact answer rather than a memory budget.
363	func TestArenaCeiling(t *testing.T) {
364		_, dec := loadCPU(t)
365		for _, side := range []int{256, 512, 1024, 1184, 1216, 1536, 2048} {
366			lat := side / 16
367			n, err := ArenaBytes(dec, lat, lat)
368			if err != nil {
369				t.Fatal(err)
370			}
371			verdict := "fits"
372			if n > MaxStorageBufferBytes {
373				verdict = "OVER maxStorageBufferRange"
374			}
375			t.Logf("%4dx%-4d latent %3dx%-3d  arena %6d MB  %s", side, side, lat, lat, n>>20, verdict)
376		}
377	}
378	
379	// TestArenaShape is what the server's geometry policy rests on, and it is a
380	// measurement rather than an argument: **the arena is a function of the pixel
381	// count alone**, at exactly 3060 bytes a pixel, whatever shape those pixels
382	// are in.
383	//
384	// It matters because the ceiling used to be a pair of side limits, inherited
385	// from z-image — whose blocked fp16 conv copies really are padded per axis,
386	// so 128x512 cost it more arena than 256x256. This decoder holds its
387	// activations flat, and nothing in the graph pads a row: an 8:1 picture plans
388	// to the same byte as the square of its area. A side ceiling would therefore
389	// have been charging every landscape request for a constraint that does not
390	// exist — 16:9 inside a 1024x1024 box is 1024x576, 56% of the pixels the same
391	// arena holds.
392	//
393	// The two controls are the extreme aspects (256x4096 and 4096x256), because
394	// an axis-dependent cost would show up there or nowhere.
395	func TestArenaShape(t *testing.T) {
396		_, dec := loadCPU(t)
397		const bytesPerPixel = 3060
398		for _, s := range [][2]int{
399			{1024, 1024}, {1344, 768}, {768, 1344}, {1152, 896}, {2048, 512},
400			{512, 2048}, {256, 4096}, {4096, 256}, {1184, 1184}, {1536, 864},
401		} {
402			w, h := s[0], s[1]
403			n, err := ArenaBytes(dec, h/16, w/16)
404			if err != nil {
405				t.Fatal(err)
406			}
407			if got := n / (w * h); got != bytesPerPixel || n%(w*h) != 0 {
408				t.Errorf("%dx%d plans %d bytes, %g a pixel; want exactly %d",
409					w, h, n, float64(n)/float64(w*h), bytesPerPixel)
410			}
411			t.Logf("%4dx%-4d  %.3f Mpx  arena %6d MB  %s",
412				w, h, float64(w*h)/1e6, n>>20,
413				map[bool]string{true: "fits", false: "OVER maxStorageBufferRange"}[n <= MaxStorageBufferBytes])
414		}
415		// The consequence, spelled out: the largest area this decoder decodes,
416		// and the largest 16:9 inside it.
417		t.Logf("budget %d pixels (%.2f Mpx); largest square 1184x1184, largest exact 16:9 1536x864",
418			MaxStorageBufferBytes/bytesPerPixel, float64(MaxStorageBufferBytes/bytesPerPixel)/1e6)
419	}
