1	// Package vae implements the Z-Image / Flux AutoencoderKL decoder: 16
2	// latent channels to RGB at 8x resolution.
3	//
4	// This is the CPU reference implementation. It exists before the Vulkan one
5	// on purpose: it separates "do I understand the architecture" from "is the
6	// shader right", and once it matches diffusers it becomes the oracle the GPU
7	// port is debugged against. It is written for clarity over speed — a direct
8	// convolution parallelised over output channels, no im2col, no blocking —
9	// because the fast version of this is a compute shader and not a smarter
10	// Go loop.
11	//
12	// Layout is NCHW float32 throughout, matching PyTorch, so a tensor here can
13	// be compared to a reference dump byte for byte with no transpose in the
14	// way.
15	package vae
16	
17	import (
18		"fmt"
19		"runtime"
20		"sync"
21	)
22	
23	// Tensor is a dense NCHW float32 tensor.
24	type Tensor struct {
25		N, C, H, W int
26		Data       []float32
27	}
28	
29	// NewTensor allocates a zeroed tensor.
30	func NewTensor(n, c, h, w int) *Tensor {
31		return &Tensor{N: n, C: c, H: h, W: w, Data: make([]float32, n*c*h*w)}
32	}
33	
34	// Len is the element count.
35	func (t *Tensor) Len() int { return t.N * t.C * t.H * t.W }
36	
37	// Plane returns the h*w slice for one image and channel.
38	func (t *Tensor) Plane(n, c int) []float32 {
39		off := ((n * t.C) + c) * t.H * t.W
40		return t.Data[off : off+t.H*t.W]
41	}
42	
43	// Shape renders the shape the way the reference manifest writes it.
44	func (t *Tensor) Shape() []int { return []int{t.N, t.C, t.H, t.W} }
45	
46	func (t *Tensor) String() string {
47		return fmt.Sprintf("[%d %d %d %d]", t.N, t.C, t.H, t.W)
48	}
49	
50	// parallelFor runs fn over [0,n) across GOMAXPROCS workers. Every heavy loop
51	// here is embarrassingly parallel over output channels, which is both the
52	// outermost loop and the one with no write aliasing between iterations.
53	func parallelFor(n int, fn func(i int)) {
54		workers := runtime.GOMAXPROCS(0)
55		if workers > n {
56			workers = n
57		}
58		if workers <= 1 {
59			for i := 0; i < n; i++ {
60				fn(i)
61			}
62			return
63		}
64		var wg sync.WaitGroup
65		next := make(chan int, n)
66		for i := 0; i < n; i++ {
67			next <- i
68		}
69		close(next)
70		wg.Add(workers)
71		for w := 0; w < workers; w++ {
72			go func() {
73				defer wg.Done()
74				for i := range next {
75					fn(i)
76				}
77			}()
78		}
79		wg.Wait()
80	}
81	
82	// Conv2D is a 2-D convolution with zero padding, weights in PyTorch's
83	// [outC, inC, kh, kw] order.
84	//
85	// Stride and PadEnd exist for the encoder's three downsamplers and are zero
86	// everywhere else. **They are one shape between them, not two knobs**:
87	// diffusers' Downsample2D pads (0, 1, 0, 1) -- nothing on the top and left,
88	// one pixel on the bottom and right -- and then convolves with stride 2 and
89	// no padding of its own. So Pad stays the symmetric padding every other
90	// convolution in this package uses, PadEnd is the extra row and column on the
91	// far side, and a zero in either is the ordinary case.
92	type Conv2D struct {
93		InC, OutC int
94		KH, KW    int
95		Pad       int
96		// PadEnd is extra zero padding on the bottom and right only.
97		PadEnd int
98		// Stride is the step between output pixels; 0 and 1 both mean 1, so that
99		// every Conv2D built before this field existed still means what it did.
100		Stride int
101		Weight []float32 // [OutC][InC][KH][KW]
102		Bias   []float32 // [OutC], may be nil
103	}
104	
105	// stride is Stride with the zero value read as 1.
106	func (c *Conv2D) stride() int {
107		if c.Stride < 1 {
108			return 1
109		}
110		return c.Stride
111	}
112	
113	// OutSize is the spatial size this convolution produces from an input side of
114	// n, which is PyTorch's formula with the two paddings separated.
115	func (c *Conv2D) OutSize(n, k int) int {
116		return (n+2*c.Pad+c.PadEnd-k)/c.stride() + 1
117	}
118	
119	// convTap, when set, is called with every convolution's input before it runs.
120	// It is how TestConvInputsFitFP16 measures the headroom the matrix-core
121	// convolution depends on -- stage 2's "absmax 497 through the whole decoder"
122	// as an assertion rather than as a memory -- without keeping a second copy
123	// of the decoder's graph in the test. Nothing in the library sets it.
124	var convTap func(c *Conv2D, x *Tensor)
125	
126	// FP16ConvOperands makes every Conv2D.Apply narrow *both* operands to IEEE
127	// binary16 before multiplying, while still accumulating in float32. That is
128	// exactly what a matrix core does, and this is the instrument IMAGE.md's Q9
129	// ledger says the conv port owes before it is written: z-image narrowed its
130	// decoder's convolutions on a graph whose activations peak at 497, Qwen's
131	// peak at 1.1e4, and "20x less headroom is still inside fp16" is an argument
132	// where the project's method wants a measurement.
133	//
134	// It narrows the *tensors*, once each, rather than each product: that is both
135	// faster and more faithful, because the device does the same -- the filter is
136	// packed to halves at load and shaders/vae_pack_conv.comp narrows the
137	// activation once into the blocked layout the fragment loads read.
138	//
139	// It is a package-level switch, like convTap above, because the port it
140	// predicts is a property of the convolution and not of a caller; nothing in
141	// the library sets it and it is not safe to flip while a decode is running.
142	var FP16ConvOperands bool
143	
144	// narrowF16 returns a copy of v with every element rounded to binary16 and
145	// back.
146	func narrowF16(v []float32) []float32 {
147		out := make([]float32, len(v))
148		for i, x := range v {
149			out[i] = safetensors.F16ToF32(safetensors.F32ToF16(x))
150		}
151		return out
152	}
153	
154	// Apply runs the convolution. Output is [N, OutC, H, W] for the 3x3 pad-1 and
155	// 1x1 pad-0 cases this decoder uses, both of which preserve spatial size.
156	func (c *Conv2D) Apply(x *Tensor) (*Tensor, error) {
157		if convTap != nil {
158			convTap(c, x)
159		}
160		if x.C != c.InC {
161			return nil, fmt.Errorf("vae: conv expects %d input channels, got %d", c.InC, x.C)
162		}
163		weight := c.Weight
164		if FP16ConvOperands {
165			weight = narrowF16(weight)
166			x = &Tensor{N: x.N, C: x.C, H: x.H, W: x.W, Data: narrowF16(x.Data)}
167		}
168		stride := c.stride()
169		outH := c.OutSize(x.H, c.KH)
170		outW := c.OutSize(x.W, c.KW)
171		if outH <= 0 || outW <= 0 {
172			return nil, fmt.Errorf("vae: conv on %s with kernel %dx%d pad %d leaves nothing", x, c.KH, c.KW, c.Pad)
173		}
174		out := NewTensor(x.N, c.OutC, outH, outW)
175	
176		for n := 0; n < x.N; n++ {
177			parallelFor(c.OutC, func(oc int) {
178				dst := out.Plane(n, oc)
179				var bias float32
180				if c.Bias != nil {
181					bias = c.Bias[oc]
182				}
183				for i := range dst {
184					dst[i] = bias
185				}
186				// Accumulate one (input channel, kernel tap) plane at a time.
187				// Holding the tap fixed makes the inner loop a contiguous
188				// strided add over a whole output row.
189				for ic := 0; ic < c.InC; ic++ {
190					src := x.Plane(n, ic)
191					wbase := ((oc * c.InC) + ic) * c.KH * c.KW
192					for kh := 0; kh < c.KH; kh++ {
193						for kw := 0; kw < c.KW; kw++ {
194							wv := weight[wbase+kh*c.KW+kw]
195							if wv == 0 {
196								continue
197							}
198							for oh := 0; oh < outH; oh++ {
199								ih := oh*stride + kh - c.Pad
200								if ih < 0 || ih >= x.H {
201									continue
202								}
203								// Clip the output-column range to where the
204								// input column is in bounds, so the inner loop
205								// carries no branch. With a stride the two
206								// bounds are the same inequality divided by it:
207								// lo rounds up and hi rounds down.
208								lo, hi := 0, outW
209								if v := ceilDiv(c.Pad-kw, stride); v > lo {
210									lo = v
211								}
212								if v := floorDiv(x.W-1+c.Pad-kw, stride) + 1; v < hi {
213									hi = v
214								}
215								if lo >= hi {
216									continue
217								}
218								drow := dst[oh*outW : (oh+1)*outW]

