	{ConvOC16, shaders.VAEConv2DOC16, 16},
	{ConvOC32, shaders.VAEConv2DOC32, 32},
	{ConvOC32IC32, shaders.VAEConv2DOC32IC32, 32},
	{ConvOC48, shaders.VAEConv2DOC48, 48},
	{ConvOC64, shaders.VAEConv2DOC64, 64},
